// Reminder 1: 'Lunch with Jordan tomorrow at 12:30' -> 12:30 PM
// Reminder 2: 'Follow up with Maya if she's not there by 6:30 PM' -> 6:30 PM
// Gap = 6:30 PM - 12:30 PM = 6 hours

const gapHours = 6;
const gapSeconds = gapHours * 3600;
console.log('Time gap: ' + gapHours + ' hours = ' + gapSeconds + ' seconds');

const baseTimestamp = 1788269400.0;
const newTimestamp = baseTimestamp + gapSeconds;
console.log('Base timestamp: ' + baseTimestamp + ' -> ' + new Date(baseTimestamp * 1000).toUTCString());
console.log('New timestamp:  ' + newTimestamp + ' -> ' + new Date(newTimestamp * 1000).toUTCString());
